<body>
  <div class="container">
    <h1>Pomodoro Timer</h1>
    <p class="hint">Work for 25 minutes, then take a 5-minute break.</p>

    <div class="timer-display" id="timerDisplay">25:00</div>
    <div class="status work" id="statusText" aria-live="polite">Ready to start</div>

    <div class="controls">
      <button id="startBtn" class="primary">Start</button>
      <button id="pauseBtn">Pause</button>
      <button id="resetBtn">Reset</button>
    </div>

    <div class="rounds" id="roundsDisplay">
      <strong>0</strong> rounds completed
    </div>

    <div class="empty-state" id="emptyState">
      Start the timer to begin your first Pomodoro round.
    </div>

    <div class="visually-hidden" aria-live="assertive" id="ariaLive"></div>
  </div>

<script>
  const WORK_DURATION = 25 * 60; // 25 minutes in seconds
  const BREAK_DURATION = 5 * 60; // 5 minutes in seconds

  let timeLeft = WORK_DURATION;
  let isRunning = false;
  let isWorkPhase = true;
  let roundsCompleted = 0;
  let intervalId = null;

  const timerDisplay = document.getElementById('timerDisplay');
  const statusText = document.getElementById('statusText');
  const startBtn = document.getElementById('startBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const roundsDisplay = document.getElementById('roundsDisplay');
  const emptyState = document.getElementById('emptyState');
  const ariaLive = document.getElementById('ariaLive');

  function formatTime(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(timeLeft);
    roundsDisplay.innerHTML = `<strong>${roundsCompleted}</strong> round${roundsCompleted !== 1 ? 's' : ''} completed`;

    if (roundsCompleted === 0 && !isRunning && timeLeft === WORK_DURATION) {
      emptyState.style.display = 'block';
    } else {
      emptyState.style.display = 'none';
    }

    if (isWorkPhase) {
      statusText.textContent = isRunning ? 'Working...' : 'Ready to start';
      statusText.className = 'status work';
    } else {
      statusText.textContent = isRunning ? 'On break...' : 'Break ready';
      statusText.className = 'status break';
    }

    startBtn.disabled = isRunning;
    pauseBtn.disabled = !isRunning;
  }

  function saveState() {
    if (window.alfy && window.alfy.storage) {
      window.alfy.storage.set('pomodoro-state', {
        timeLeft,
        isWorkPhase,
        roundsCompleted
      });
    }
  }

  function loadState() {
    if (window.alfy && window.alfy.storage) {
      window.alfy.storage.get('pomodoro-state').then(saved => {
        if (saved) {
          timeLeft = saved.timeLeft;
          isWorkPhase = saved.isWorkPhase;
          roundsCompleted = saved.roundsCompleted;
          updateDisplay();
        }
      });
    }
  }

  function tick() {
    if (timeLeft > 0) {
      timeLeft--;
      updateDisplay();
      saveState();
    } else {
      clearInterval(intervalId);
      isRunning = false;

      if (isWorkPhase) {
        roundsCompleted++;
        ariaLive.textContent = `Round ${roundsCompleted} completed. Time for a break.`;
        isWorkPhase = false;
        timeLeft = BREAK_DURATION;
      } else {
        ariaLive.textContent = `Break finished. Ready for another round.`;
        isWorkPhase = true;
        timeLeft = WORK_DURATION;
      }

      updateDisplay();
      saveState();

      // Auto-start the next phase
      setTimeout(() => {
        if (!isRunning) {
          isRunning = true;
          intervalId = setInterval(tick, 1000);
          updateDisplay();
        }
      }, 1000);
    }
  }

  startBtn.addEventListener('click', () => {
    if (!isRunning) {
      isRunning = true;
      intervalId = setInterval(tick, 1000);
      updateDisplay();
      saveState();
    }
  });

  pauseBtn.addEventListener('click', () => {
    if (isRunning) {
      isRunning = false;
      clearInterval(intervalId);
      updateDisplay();
      saveState();
    }
  });

  resetBtn.addEventListener('click', () => {
    isRunning = false;
    clearInterval(intervalId);
    timeLeft = WORK_DURATION;
    isWorkPhase = true;
    roundsCompleted = 0;
    updateDisplay();
    saveState();
  });

  // Initialize
  loadState();
  updateDisplay();
</script>
</body>
